;
; Purpose: dav1d's assembly configuration for ELF. The checked-in config.asm was generated by
; Meson for Windows: it sets ARCH_X86_64 for win64 and x64 and leaves its %else branch empty, so
; under elf64 the architecture stays 0 and every source assembles as 32-bit code into a 64-bit
; object. This file is put ahead of it on nasm's include path rather than edited in place.

%define ARCH_X86_32 0
%define ARCH_X86_64 0

%ifidn __OUTPUT_FORMAT__,elf32
    %define ARCH_X86_32 1
    %define STACK_ALIGNMENT 16
%elifidn __OUTPUT_FORMAT__,elf64
    %define ARCH_X86_64 1
    %define STACK_ALIGNMENT 16
%elifidn __OUTPUT_FORMAT__,macho64
    ; Mach-O keeps the leading underscore that ELF drops.
    %define ARCH_X86_64 1
    %define PREFIX 1
    %define STACK_ALIGNMENT 16
%endif

%define FORCE_VEX_ENCODING 0

%define PIC 1

%define private_prefix dav1d
